<div class="gamification-admin-head"><h2><?php echo $this->lang('Awards') ?></h2><?php echo $this->button_create('admin/awards/add', (string)$this->lang('Create award')) ?></div><div class="table-responsive"><table class="table"><thead><tr><th><?php echo $this->lang('Award') ?></th><th><?php echo $this->lang('Team') ?></th><th><?php echo $this->lang('Date') ?></th><th><?php echo $this->lang('Ranking') ?></th><th><?php echo $this->lang('Actions') ?></th></tr></thead><tbody><?php foreach ($awards as $row): ?><tr><td><a href="<?php echo url('admin/awards/edit/'.$row['award_id']) ?>"><?php echo utf8_htmlentities($row['title']) ?></a></td><td><?php echo utf8_htmlentities($row['team_title'] ?? '') ?></td><td><?php echo utf8_htmlentities($row['awarded_at']) ?></td><td>#<?php echo (int)$row['ranking'] ?></td><td><?php echo $this->button_update('admin/awards/edit/'.$row['award_id']) ?><?php echo $this->button_delete('admin/awards/delete/'.$row['award_id']) ?></td></tr><?php endforeach ?></tbody></table></div>
